// ============================================================================
// Interlaken_v1_2_apb: APB4 register wrapper around Interlaken_v1_2_top (generated by
// scripts/apb/gen_apb.py from scripts/apb/specs/Interlaken_v1_2.json; do not edit)
// ----------------------------------------------------------------------------
//  - APB4 slave, zero wait states (PREADY = PSEL & PENABLE), 32-bit data,
//    12-bit byte address; PSLVERR on an unmapped or misaligned access.
//  - PSTRB byte lanes apply to every writable register.
//  - The core runs on PCLK/PRESETN; protocol pins pass through unchanged.
//  - Register map: docs/ip/Interlaken_v1_2.md
// ============================================================================
module Interlaken_v1_2_apb #(
  parameter int MF = 64,
  parameter int BMAX = 8,
  parameter logic [57:0] SEED = 58'h2F0_1234_5678_9ABC
) (
  input  logic        PCLK,
  input  logic        PRESETN,
  input  logic        PSEL,
  input  logic        PENABLE,
  input  logic        PWRITE,
  input  logic [11:0] PADDR,
  input  logic [31:0] PWDATA,
  input  logic [3:0]  PSTRB,
  output logic [31:0] PRDATA,
  output logic        PREADY,
  output logic        PSLVERR,
  output logic        irq,
  output logic tx_p,
  input logic rx_p
);
  localparam logic [31:0] ID_VALUE = 32'h494C0200;

  // ---------------- APB decode ----------------
  wire        acc     = PSEL & PENABLE;
  wire        wr      = acc & PWRITE;
  wire        rd      = acc & ~PWRITE;
  wire [31:0] wmask   = {{8{PSTRB[3]}}, {8{PSTRB[2]}}, {8{PSTRB[1]}}, {8{PSTRB[0]}}};
  logic [13:0] hit;
  always_comb begin
    hit = '0;
    if (PADDR[1:0] == 2'b00 && PADDR[11:2] < 10'd14) hit[PADDR[11:2]] = 1'b1;
  end
  assign PREADY  = acc;
  assign PSLVERR = acc & ~|hit;

  // ---------------- core ----------------
  logic          c_tx_valid;
  logic          c_tx_ready;
  logic [63:0]   c_tx_data;
  logic          c_tx_sop;
  logic          c_tx_eop;
  logic [2:0]    c_tx_bytes;
  logic [7:0]    c_tx_chan;
  logic [15:0]   c_tx_fc;
  logic          c_rx_valid;
  logic [63:0]   c_rx_data;
  logic          c_rx_sop;
  logic          c_rx_eop;
  logic [2:0]    c_rx_bytes;
  logic [7:0]    c_rx_chan;
  logic          c_rx_err;
  logic [15:0]   c_rx_fc;
  logic          c_word_lock;
  logic          c_sync_lock;
  logic [1:0]    c_peer_status;
  logic          c_err_word;
  logic          c_err_sync;
  logic          c_err_scr;
  logic          c_err_crc32;
  logic          c_err_crc24;
  logic          c_err_proto;
  Interlaken_v1_2_top #(.MF(MF), .BMAX(BMAX), .SEED(SEED)) u_core (
    .clk(PCLK),
    .rst_n(PRESETN),
    .tx_p(tx_p),
    .rx_p(rx_p),
    .tx_valid(c_tx_valid),
    .tx_ready(c_tx_ready),
    .tx_data(c_tx_data),
    .tx_sop(c_tx_sop),
    .tx_eop(c_tx_eop),
    .tx_bytes(c_tx_bytes),
    .tx_chan(c_tx_chan),
    .tx_fc(c_tx_fc),
    .rx_valid(c_rx_valid),
    .rx_data(c_rx_data),
    .rx_sop(c_rx_sop),
    .rx_eop(c_rx_eop),
    .rx_bytes(c_rx_bytes),
    .rx_chan(c_rx_chan),
    .rx_err(c_rx_err),
    .rx_fc(c_rx_fc),
    .word_lock(c_word_lock),
    .sync_lock(c_sync_lock),
    .peer_status(c_peer_status),
    .err_word(c_err_word),
    .err_sync(c_err_sync),
    .err_scr(c_err_scr),
    .err_crc32(c_err_crc32),
    .err_crc24(c_err_crc24),
    .err_proto(c_err_proto)
  );

  // ---------------- registers ----------------
  logic [9:0] irq_status, irq_enable, irq_set;
  logic [31:0] scratch;
  logic [15:0] r_FC;   // 12'h014 FC
  logic [31:0] h_TX0;   // 12'h018 TX0 holding register
  logic [31:0] h_TX1;   // 12'h01C TX1 holding register
  logic [12:0] h_TX2;   // 12'h020 TX2 holding register
  logic [31:0] h_RX0;   // 12'h024 RX0 holding register
  logic [31:0] h_RX1;   // 12'h028 RX1 holding register
  logic [13:0] h_RX2;   // 12'h02C RX2 holding register
  logic full_TX;
  logic avail_RX;

  always_ff @(posedge PCLK or negedge PRESETN) begin
    if (!PRESETN) begin
      irq_status <= '0; irq_enable <= '0; scratch <= '0;
      r_FC <= 16'h0;
      h_TX0 <= '0;
      h_TX1 <= '0;
      h_TX2 <= '0;
      h_RX0 <= '0;
      h_RX1 <= '0;
      h_RX2 <= '0;
      full_TX <= 1'b0;
      avail_RX <= 1'b0;
    end else begin
      irq_status <= (irq_status & ~((wr && hit[1]) ? PWDATA[9:0] & wmask[9:0] : '0)) | irq_set;
      if (wr && hit[2]) irq_enable <= (irq_enable & ~wmask[9:0]) | (PWDATA[9:0] & wmask[9:0]);
      if (wr && hit[4]) scratch <= (scratch & ~wmask) | (PWDATA & wmask);
      if (wr && hit[5]) r_FC <= (r_FC & ~wmask[15:0]) | (PWDATA[15:0] & wmask[15:0]);
      if (wr && hit[6] && !full_TX) h_TX0 <= (h_TX0 & ~wmask[31:0]) | (PWDATA[31:0] & wmask[31:0]);
      if (wr && hit[7] && !full_TX) h_TX1 <= (h_TX1 & ~wmask[31:0]) | (PWDATA[31:0] & wmask[31:0]);
      if (wr && hit[8] && !full_TX) h_TX2 <= (h_TX2 & ~wmask[12:0]) | (PWDATA[12:0] & wmask[12:0]);
      if (wr && hit[8] && !full_TX) full_TX <= 1'b1;
      else if (full_TX && c_tx_ready) full_TX <= 1'b0;
      if (c_rx_valid && (!avail_RX || (rd && hit[11]))) begin
        h_RX0[31:0] <= c_rx_data[31:0];
        h_RX1[31:0] <= c_rx_data[63:32];
        h_RX2[0:0] <= c_rx_sop;
        h_RX2[1:1] <= c_rx_eop;
        h_RX2[4:2] <= c_rx_bytes[2:0];
        h_RX2[12:5] <= c_rx_chan[7:0];
        h_RX2[13:13] <= c_rx_err;
        avail_RX <= 1'b1;
      end else if (rd && hit[11]) avail_RX <= 1'b0;
    end
  end

  // ---------------- core inputs ----------------
  assign c_tx_fc = r_FC[15:0];
  assign c_tx_data[31:0] = h_TX0[31:0];
  assign c_tx_data[63:32] = h_TX1[31:0];
  assign c_tx_sop = h_TX2[0:0];
  assign c_tx_eop = h_TX2[1:1];
  assign c_tx_bytes[2:0] = h_TX2[4:2];
  assign c_tx_chan[7:0] = h_TX2[12:5];
  assign c_tx_valid = full_TX;

  // ---------------- interrupts and flags ----------------
  always_comb begin
    irq_set = '0;
    irq_set[0] = c_err_word;
    irq_set[1] = c_err_sync;
    irq_set[2] = c_err_scr;
    irq_set[3] = c_err_crc32;
    irq_set[4] = c_err_crc24;
    irq_set[5] = c_err_proto;
    irq_set[6] = full_TX & c_tx_ready;
    irq_set[7] = wr & (hit[6] | hit[7] | hit[8]) & full_TX;
    irq_set[8] = c_rx_valid & (~avail_RX | (rd & hit[11]));
    irq_set[9] = c_rx_valid & avail_RX & ~(rd & hit[11]);
  end
  assign irq = |(irq_status & irq_enable);
  wire [1:0] flags = {avail_RX, full_TX};

  // ---------------- read mux ----------------
  logic [31:0] apb_rdata;
  always_comb begin
    apb_rdata = '0;
    case (PADDR[11:2])
      10'd0: apb_rdata = ID_VALUE;
      10'd1: apb_rdata = 32'(irq_status);
      10'd2: apb_rdata = 32'(irq_enable);
      10'd3: apb_rdata = 32'(flags);
      10'd4: apb_rdata = scratch;
      10'd5: apb_rdata = 32'(r_FC);
      10'd6: apb_rdata = 32'(h_TX0);
      10'd7: apb_rdata = 32'(h_TX1);
      10'd8: apb_rdata = 32'(h_TX2);
      10'd9: apb_rdata = 32'(h_RX0);
      10'd10: apb_rdata = 32'(h_RX1);
      10'd11: apb_rdata = 32'(h_RX2);
      10'd12: apb_rdata = 32'({c_rx_fc});
      10'd13: apb_rdata = 32'({c_peer_status, c_sync_lock, c_word_lock});
      default: apb_rdata = '0;
    endcase
  end
  assign PRDATA = (rd && |hit) ? apb_rdata : '0;
endmodule
